    for line in TEXT.splitlines():
        if not line:continue
        if line.startswith('@'):block=int(line[1:]);continue
        code,*entry=line.split('|')
        if code.startswith('S'):ident=f'SC3_B{block}_STYLE_'+code[1:]
        elif code.startswith('C'):ident=f'SC3_B{block}_CHOICE_'+code[1:]
        else:ident=f'DK4_MES_B{block}_R{int(code):04d}'
        rows.append([ident,*entry])
    drafts=load(ROOT/'all349_independent_drafts_v1.json')
    assert [r[0] for r in rows]==[r['id'] for r in drafts['records']] and len(rows)==349
    save(output,dict(blocks=list(range(275,286)),records=rows,complete_source_current_exchanges_read=True,
        all_five_gates_still_pending=True,new_credit=0,native_names_androles_bound_terms_individual_name_review_andfresh_display_pending=True))
